        // 기본정보조회
        const sbmOptions = {
            id : "sbm_dts_corp_basic",
            action : "/CorporationInfo.do",
            ref : "",
            target : "dts_corp_basic=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        panel_2.show("");
    } else {
        panel_2.hide();
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !접수정보--;
