/**
 * @method
 * @name showAlertMsg
 * @description 공시검토처리시 경고 메세지 보여주기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showAlertMsg = async function() {
    let vAlertMsg = "";
    let vMsgCnt = 0;

    //  유가시장일때
    if (scwin.gDoc_LdMktTp === '1') {
        if (scwin.gCd024 === "T" && scwin.gCd031 === "F") {
            // alert("◆ 주의 사항 ◆\n\n"+
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 매매거래정지기준에 해당할 수 있는 중요내용공시입니다. \n" + "매매거래정지기준에 해당하는 경우 주식시장총괄팀, \n" + "채권시장총괄팀 등에 조치·통보하시기 바랍니다.");
            vMsgCnt++;
        }
        if (scwin.gCd024 === "T" && scwin.gCd031 === "T") {
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 매매거래정지 또는 우회상장에 해당할 수 있는 중요내용공시입니다.\n" + " 확인 후 해당하는 경우 조치하시기 바랍니다.");
            vMsgCnt++;
        }
        if (scwin.gCd024 === "F" && scwin.gCd031 === "T") {
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 우회상장 해당여부를 확인하고 조치하시기 바랍니다.");
            vMsgCnt++;
        }
        if (scwin.gCd028 === "T") {
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 발행주식수 변경내역을 확인하시고  관련부서에 통보하시기 바랍니다.");
            vMsgCnt++;
        }
        if (scwin.gCd029 === "T") {
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 신주배정기준일 기준 신주발행가액(1차 발행가) 공시의 경우\n" + " 발행주식수 변경내역을 관련부서에 통보하시기 바랍니다.");
            vMsgCnt++;
        }
        if (scwin.gCd035 === "T") {
            // 034와 연관됨
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            /*
            vAlertMsg += ("◆ 주의 사항 ◆\n\n"+
            	" 해당 공시내용은 시황급변 조회공시 요구에 대한 답변공시 \n"+
            	" 이후 15일내에 제출된 것으로서 번복대상 중요사실(세칙 §9)에 해당될 수 있으니\n"+
            	" 주의하십시오!");
             */
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 시황관련 조회공시 번복 또는 심사대상 해당여부를 확인바랍니다.");
            vMsgCnt++;
        }
        if (scwin.gCd037 === "T") {
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            /*
            vAlertMsg += ("◆ 주의 사항 ◆\n\n"+
            	" 해당 공시내용은 풍문 등 조회공시 요구에 대한 부인공시 이후 3월내에   \n  "+
            	" 제출된 것으로서 공시번복 대상(공시규정 §30)에 해당될 수 있으니 주의하십시오!");
             */
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 풍문관련 조회공시 번복 또는 심사대상 해당여부를 확인바랍니다.");
            vMsgCnt++;
        }
        // 소액공모 연간한도 확인 추가 by LDJ_20121015
        if (scwin.gCd084 === "T") {
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 소액공모 연간한도(CB, BW 및 유상증자 합산 연간 10억원)확인 필요 ");
            vMsgCnt++;
        }

        // 납입일 2주전 주주통지 공고여부 확인 필요 by LDJ_20121015
        if (scwin.gCd085 === "T") {
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 제3자배정 유상증자 또는 일반공모의 경우, 납입일 2주전 주주통지·공고여부 확인 필요 ");
            vMsgCnt++;
        }

        // 사전확인면제대상법인 (수시)해제 사유발생(검토/승인시 경고메세지 발송용도) by LDJ_20130422
        if (scwin.gCd101 === "T") {
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + "관리종목으로 지정된 법인 및 상장폐지 사유가 발생한 법인은 공시내용 확인절차 대상 법인입니다. \n" + "동사에 대한 확인절차 대상법인 지정 조치 여부를 반드시 확인하시기 바랍니다.");
            vMsgCnt++;
        }

        //  리츠(REITs)관련 관리종목 지정 안내(검토/승인메세지용도) 20161111
        //  gSecuGrpRT(회사속성이 Y부동산투자 - 종목이 있을경우)
        if (scwin.gCd105 === "T" && scwin.gSecuGrpRT === "Y") {
            if (vMsgCnt > 0) {
                vAlertMsg += "\n\n--------------------------------------------------------\n\n";
            }
            vAlertMsg += ("◆ 주의 사항 ◆\n\n" + " 부동산투자회사인 유가증권시장 주권상장법인의 공시입니다.\n" + "하단에 [부동산투자회사의 부동산개발사업 투자비율 변경내역]을\n" + "기재했는지 확인하시고 관리종목 지정 기준 등에 해당하는지 반드시\n" + "확인하시기 바랍니다.");
