/**
 * @method
 * @name popupDocOpen
 * @description popup Doc Open 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popupDocOpen = async function() {
    let vViewLangTpCd;
    if (scwin.gSubmitSysTp === '0' && scwin.gLangTpCd === '1') {
        // 국문제출에서 영문공시를 볼
        vViewLangTpCd = '0';
    } else {
        vViewLangTpCd = scwin.gViewLangTpCd;
    }
    let usrp = "/dsclproc/JLDSTF10002.jsp";
    scwin.gPrintUrl = "/Viewer.do?method=readDsclDocPrintContent" + "&ACPT_NO=" + scwin.gPrintAcptNo + "&DOC_NO=" + scwin.gPrintDocNo + "&FORM_CD=" + scwin.gPrintFormCd + "&FORM_VER=" + scwin.gPrintFormVer + "&VIEW_LANG_TP_CD=" + vViewLangTpCd + "&SUBMIT_SYS_TP_CD=" + scwin.gSubmitSysTp + "&gAskScrenID=" + scwin.gAskScrenID + "&gAccssAuthTpCd=" + scwin.gAccssAuthTpCd + "&SCREN_ID=" + 'ULDSTF10007.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05;
    let winTitle = "공시뷰어";
    sessionStorage.setItem("gPrintUrl", scwin.gPrintUrl);
    const randNum = Math.floor(Math.random() * (99999)) + 1;

    // test
    let param = "?";
    param += "docUrl=" + scwin.gDocUrl + "&";
    param += "printType=" + scwin.gSndlocTpCd + "&";
    param += "vFromUpclssCd=" + scwin.gFromUpclssCd + "&";
    param += "printAcptNo=" + scwin.gPrintAcptNo + "&";
    param += "printDocNo=" + scwin.gPrintDocNo + "&";
    param += "gPrintUrl=" + encodeURIComponent(scwin.gPrintUrl) + "&";
    param += "procs_063=" + scwin.gProcs_063 + "&";
    param += "procs_070=" + scwin.gProcs_070 + "&";
    param += "gLangTpCd=" + scwin.gLangTpCd + "&";
    param += "gSvcStatYn=" + scwin.gSvcStatYn + "&";
    param += "submitSysTp=" + scwin.gSubmitSysTp + "&";
    param += "gAttachDocYn=" + scwin.gAttachDocYn + "&";
    param += "procs_111=" + scwin.gProcs_111 + "&";
    param += "gSecuGrpEF=" + scwin.gSecuGrpEF + "&";
    param += "gDisclsEnYn=" + scwin.gDisclsEnYn + "&";
    param += "gAcptNo=" + scwin.gAcptNo + "&";
    param += "gSvrGubun=" + js_svrGubun;
    if (typeof($c.frame.path("/").GWinOpen) === "undefined") {
        // frame.CreateDialogFrame("viewer_pop"+randNum, usrp , winTitle ,10, 10, 900, 700, "window");
        await $c.frame.CreateDialogFrame("viewer_pop" + randNum, usrp + param, winTitle, 10, 10, 900, 700, "window");
