/**
 * @method
 * @name printOpen
 * @description 인쇄하기 화면오픈
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.printOpen = async function() {
    // alert(gDocUrl : gDocUrl);
    let printType = scwin.gSndlocTpCd;
    let vFromUpclssCd = scwin.gFromUpclssCd;
    // alert("gPrintAcptNo:"+gPrintAcptNo);
    // alert("gPrintDocNo:"+gPrintDocNo);

    // 인쇄화면 파라메터 전달
    sessionStorage.setItem("gDocUrl", scwin.gDocUrl);
    sessionStorage.setItem("gSndlocTpCd", scwin.gSndlocTpCd);
    sessionStorage.setItem("gFromUpclssCd", scwin.gFromUpclssCd);
    sessionStorage.setItem("gPrintAcptNo", scwin.gPrintAcptNo);
    sessionStorage.setItem("gPrintDocNo", scwin.gPrintDocNo);
    if (printType === '20' && vFromUpclssCd !== '01') {
        // 수시공시는 제외
        let usrl = "/disclsdocviewer/pdfView.jsp?type=pdf" + "&acptNo=" + scwin.gPrintAcptNo + "&docNo=" + scwin.gPrintDocNo + "&SCREN_ID=" + 'ULDSTF10007.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&docpath=" + scwin.gDocUrl;
        let winTitle = "공시뷰어";
        await $c.frame.CreateDialogFrame("testPop", usrl, winTitle, 10, 10, 900, 700, "window");
    } else {
        await scwin.popupDocOpen();
    }
};

/**
 * @method
