    scwin.gListInvstgMiscTpCd = dts_AcptProcs.getCellData(1, "LIST_INVSTG_MISC_TP_CD");
    scwin.gPharmaBioComYn = dts_AcptProcs.getCellData(1, "PHARMA_BIO_COM_YN");
    scwin.gFormWarnContn = dts_AcptProcs.getCellData(1, "FORM_WARN_CONTN");
    scwin.gAtsIsuYn = dts_AcptProcs.getCellData(1, "ATS_ISU_YN");
    scwin.gMktclsYn = dts_AcptProcs.getCellData(1, "MKTCLS_YN");
    scwin.gAtsTrnsmYn = dts_AcptProcs.getCellData(1, "ATS_TRNSM_YN");
    scwin.gAtsTrnsmRsltCd = dts_AcptProcs.getCellData(1, "ATS_TRNSM_RSLT_CD");
    scwin.gBatchReservYn = dts_AcptProcs.getCellData(1, "BATCH_RESERV_YN");

    // alert(gAcptNo+","+  vDocNo+","+gMainFormCd+","+gFormVer);

    // 인쇄화면 파라메터 전달 2022.04.29
    sessionStorage.setItem("gProcs_063", scwin.gProcs_063);
    sessionStorage.setItem("gProcs_070", scwin.gProcs_070);
    sessionStorage.setItem("gLangTpCd", scwin.gLangTpCd);
    sessionStorage.setItem("gSvcStatYn", scwin.gSvcStatYn);
