            } else {
                txt_skil_specl.setValue("일반기업");
            }
        }
    }
    scwin.showLangBtn(scwin.gProcs_063, scwin.gProcs_070, scwin.gSubmitSysTp, scwin.gProcs_111, scwin.gDisclsEnYn); // 언어선택구분
    await scwin.readEqytyOptBigYn();
    scwin.showProcStatTitle();
    // fn_getProcObjYn();    // 처리버튼 생성유무
    /*
