 * @hidden N
 */
scwin.img_kor_onclick = async function() {
    if (img_kor.src === '../img/btn_korean.gif') {
        img_kor.setBackgroundImage('../img/btn_korean_1.gif');
        img_eng.setBackgroundImage('../img/btn_english.gif');
    } else {
        img_kor.setBackgroundImage('../img/btn_korean.gif');
        img_eng.setBackgroundImage('../img/btn_english_1.gif');
    }
    await scwin.getBodyContentByLangGb("KO");
};

