 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    fn_GetParentValue();
    scwin.setValue();
    $c.cm.PanelToGroupBox(panel_1); // 패널라운드 처리
    label_EQTYOPT.hide();
    label_BIG.hide();
    panel_actpno.show("");
    pnl_lang_btn.hide();
    btn_mod_dscl_req_acpt.hide();
    LIMIT_ISU.hide();
    lbl_skil_specl.hide(); // 기술특례여부 코스닥만 보이도록 20211126
    txt_skil_specl.hide(); // 기술특례여부 코스닥만 보이도록 20211126

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_AcptProcs",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_AcptProcs=body.content",
